def input_values(obj):
    mod=obj.modifiers[0]
    return {s.name:getattr(mod.properties.inputs,s.identifier).value
        for s in mod.node_group.interface.items_tree if s.item_type=='SOCKET'
        and s.in_out=='INPUT' and s.socket_type!='NodeSocketGeometry'}


def set_inputs(obj,values):
    mod=obj.modifiers[0]
    for socket in mod.node_group.interface.items_tree:
        if socket.item_type=='SOCKET' and socket.in_out=='INPUT' and socket.name in values:
            getattr(mod.properties.inputs,socket.identifier).value=values[socket.name]


def _control_drivers(parent,child):
    """Native single-property drivers keep shared modifier controls live."""
    def props(obj):
        mod=obj.modifiers[0]
        return {s.name:getattr(mod.properties.inputs,s.identifier)
            for s in mod.node_group.interface.items_tree if s.item_type=='SOCKET'
            and s.in_out=='INPUT' and s.socket_type in ('NodeSocketFloat','NodeSocketInt')}
    source=props(parent);target=props(child)
    for key in ('Metres to Blender Units','Mesh Resolution','Cell Size',
                'Height Exaggeration','Samples Per Side','Relax Iterations'):
        target[key].driver_remove('value')
        curve=target[key].driver_add('value');driver=curve.driver
        driver.type='AVERAGE'
        # Blender's default identity curve has Bezier keys. Its numerical
        # inversion can turn 0.5 into 0.49999994, changing integer subdivision
        # counts. These controls are direct copies, not animation remappings.
        curve.extrapolation='LINEAR'
        for point in curve.keyframe_points:point.interpolation='LINEAR'
        variable=driver.variables.new();variable.name='control';variable.type='SINGLE_PROP'
        variable.targets[0].id=parent;variable.targets[0].data_path=source[key].path_from_id('value')


def values(mesh,key):
    return [v.value for v in mesh.attributes[key].data]


def _subset(mesh,vertices,edges,label):
    lookup={old:new for new,old in enumerate(vertices)}
    out=bpy.data.meshes.new(label)
    # These are private source lookups. All coordinates are overwritten by GN.
    out.from_pydata([(0.,0.,0.)]*len(vertices),[tuple(lookup[v] for v in mesh.edges[i].vertices) for i in edges],[])
    for attr in mesh.attributes:
        if attr.name.startswith('.') or attr.name=='position':continue
        if attr.domain not in ('POINT','EDGE'):
            if not len(attr.data):continue
            raise ValueError('Unexpected source-binding domain: '+attr.name)
        selected=vertices if attr.domain=='POINT' else edges
        field,size=('vector',3) if attr.data_type=='FLOAT_VECTOR' else ('value',1)
        if attr.data_type not in ('FLOAT_VECTOR','FLOAT','INT','BOOLEAN'):
            raise ValueError('Unexpected source-binding attribute type')
        data=np.empty(len(attr.data)*size,dtype=np.float64 if attr.data_type.startswith('FLOAT') else np.int32)
        attr.data.foreach_get(field,data)
        data=data.reshape(-1,size)[selected].reshape(-1)
        out.attributes.new(attr.name,attr.data_type,attr.domain).data.foreach_set(field,data)
    return out,lookup


def owner_sites(tables):
    """Every ordinary, compound or logical patch leader with its exact members."""
    sites={i:(i,) for i in range(len(tables['Junctions'].data.vertices))}
    pairs=tables['Compounds'].data
    for a,b in zip(values(pairs,'st_cp_site_a'),values(pairs,'st_cp_site_b')):
        sites[a]=(a,b);del sites[b]
    declarations=tables['Logical Clusters'].data;members=tables['Cluster Sites'].data
    for owner,leader in enumerate(values(declarations,'st_lg_site')):
        group=tuple(s for s,k in zip(values(members,'st_lc_site'),values(members,'st_lc_owner')) if k==owner)
        assert group and leader==min(group)
        for s in group:
            if s!=leader:del sites[s]
        sites[leader]=group
    return sites


def owner_programs(tables):
    """Use the same predicates as the saved, guarded native owner programs."""
    from .patch_program_selection import owner_program_kinds
    junctions=tables['Junctions'].data;approaches=tables['Approaches'].data
    pairs=tables['Compounds'].data;declarations=tables['Logical Clusters'].data
    members=tables['Cluster Sites'].data
    cluster_sites=values(members,'st_lc_site');cluster_owners=values(members,'st_lc_owner')
    clusters=[tuple(s for s,k in zip(cluster_sites,cluster_owners) if k==owner)
              for owner in range(len(declarations.vertices))]
    if [min(group) for group in clusters]!=values(declarations,'st_lg_site'):
        raise ValueError('Logical constructor leader differs from prepared membership')
    starts=values(junctions,'st_cj_range_start');counts=values(junctions,'st_cj_range_count')
    kinds=values(approaches,'st_pp_kind')
    seams=[i for i,(start,count) in enumerate(zip(starts,counts)) if count==2 and kinds[start]==3]
    result=owner_program_kinds(len(junctions.vertices),
        zip(values(pairs,'st_cp_site_a'),values(pairs,'st_cp_site_b')),clusters,seams)
    if set(result)!=set(owner_sites(tables)):
        raise ValueError('Constructor routing differs from prepared patch leaders')
    return result


def scope(obj,tables,sites,collection,label,*,required_streets=()):
    """Rebase private source/mapping indices to existing dependency objects."""
    binding=tables['Source Binding'].data;mapping=tables['Mapping'].data
    junctions=tables['Junctions'].data;approaches=tables['Approaches'].data
    required=set(required_streets)
    for at in sites:
        start=values(junctions,'st_cj_range_start')[at];count=values(junctions,'st_cj_range_count')[at]
        required.update(values(approaches,'st_cj_street_id')[start:start+count])
    # A terminal tangent depends on the adjoining original Street's first
    # chord. Add those existing source objects even for the patch at the other
    # end of the current Street. Peer indices address the unchanged global span
    # table, whose source ranges are rebased below along with all other ranges.
    source_ids=values(mapping,'st_ps_street_id')
    direct=set(required)
    for key in ('st_ps_seam_start_span','st_ps_seam_end_span'):
        if key not in mapping.attributes:continue
        for sid,peer in zip(source_ids,values(mapping,key)):
            if sid in direct and peer>=0:
                if peer>=len(source_ids):raise ValueError('Seam peer is outside the original span inventory')
                required.add(source_ids[peer])
    street_ids=values(binding,'st_street_id');canonical_edges=values(binding,'_pv_edge')
    wanted={canonical_edges[i] for i,sid in enumerate(street_ids) if sid in required}
    dependencies=[s for s in tables['Source Objects'].all_objects if
        wanted.intersection(values(s.data,'st_live_edge_index'))]
    if not dependencies:raise ValueError('Patch owner has no canonical source dependencies')
    points=sorted(v for s in dependencies for v in values(s.data,'st_live_vertex_index'))
    edges=sorted(v for s in dependencies for v in values(s.data,'st_live_edge_index'))
    if len(set(points))!=len(points) or len(set(edges))!=len(edges):raise ValueError('Repeated canonical source identity')
    point_map={v:i for i,v in enumerate(points)};edge_map={e:i for i,e in enumerate(edges)}
    selected_edges=[i for i,e in enumerate(canonical_edges) if e in edge_map]
    selected_vertices=sorted({v for i in selected_edges for v in binding.edges[i].vertices})
    view,view_points=_subset(binding,selected_vertices,selected_edges,label+' source view')
    view_edges={v:i for i,v in enumerate(selected_edges)}
    for key,lookup,optional in (('_pv_vertex',point_map,False),('_pv_alias',point_map,True),
                                ('_pv_edge',edge_map,False),('_pv_first',point_map,False),('_pv_last',point_map,False)):
        attr=view.attributes[key]
        attr.data.foreach_set('value',[v.value if optional and v.value<0 else lookup[v.value] for v in attr.data])
    mapped=mapping.copy();mapped.name=label+' span lookups'
    for at in range(len(mapped.vertices)):
        start=mapped.attributes['st_ps_start'].data[at].value
        edge=mapped.attributes['st_ps_edge_start'].data[at].value
        count=mapped.attributes['st_ps_count'].data[at].value
        selected=start in view_points
        if selected and any(v not in view_points for v in range(start,start+count)):
            raise ValueError('A dependency would split an authored Street')
        mapped.attributes['st_ps_start'].data[at].value=view_points[start] if selected else -1
        mapped.attributes['st_ps_edge_start'].data[at].value=view_edges[edge] if selected else -1
        if not selected:mapped.attributes['st_ps_count'].data[at].value=0
    order=bpy.data.meshes.new(label+' canonical identity order')
    source_edges={}
    for s in dependencies:
        p=values(s.data,'st_live_vertex_index');e=values(s.data,'st_live_edge_index')
        for index,edge in zip(e,s.data.edges):source_edges[index]=tuple(point_map[p[v]] for v in edge.vertices)
    order.from_pydata([(0.,0.,0.)]*len(points),[source_edges[e] for e in edges],[])
    order.attributes.new('st_live_vertex_index','INT','POINT').data.foreach_set('value',points)
    order.attributes.new('st_live_edge_index','INT','EDGE').data.foreach_set('value',edges)
    source_collection=bpy.data.collections.new(label+' live dependencies');collection.children.link(source_collection)
    for source in dependencies:source_collection.objects.link(source)
