    for key,mesh in (('Source Binding',view),('Source Order',order),('Mapping',mapped)):
        private=bpy.data.objects.new(label+' / '+key,mesh);collection.objects.link(private)
        private.hide_set(True);private.hide_render=True;result[key]=private
    return result,tuple(s.name for s in dependencies)


