        set_inputs(part,dict(tables,**inputs,**{'Owner Index':at}))
        part.hide_set(True);part.hide_render=True;part['st_cached_patch_owner']=at
        if provider_programs is not None:part['st_cached_patch_program_kind']=kinds[at]
